starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "parameter_name" {
  description = "Input variable parameter_name."
  type        = string
  default     = "/app/config"
}

variable "parameter_value" {
  description = "Input variable parameter_value."
  type        = string
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_ssm_parameter" "this" {
  # TODO - Complete the aws_ssm_parameter resource.
  # Add the arguments and nested blocks required for aws_ssm_parameter.
}
